package com.bank.schema.read;

import com.bank.schema.model.TypedTxn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// SCHEMA-ON-READ: store raw strings now; apply structure only when reading.
public class SchemaOnReadStore {
    private static final Logger log = Logger.getLogger(SchemaOnReadStore.class.getName());
    private final List<String> rawRecords = new ArrayList<>();

    // Write accepts ANYTHING — no validation at write time (fast, flexible).
    public void write(String csvLine) {
        rawRecords.add(csvLine);
        log.fine(() -> "RAW stored (no validation): " + csvLine);
    }

    // Structure is imposed HERE, at read time — may fail on bad data.
    public List<TypedTxn> readAs() {
        log.info("SCHEMA-ON-READ: applying structure at read time");
        List<TypedTxn> out = new ArrayList<>();
        for (String line : rawRecords) {
            try {
                String[] p = line.split(",");
                out.add(new TypedTxn(p[0], p[1], new BigDecimal(p[2])));
            } catch (RuntimeException ex) {
                log.warning(() -> "Read-time parse failure for: " + line);
            }
        }
        return out;
    }

    public List<String> raw() { return rawRecords; }
}
