package com.bank.schema.write;

import com.bank.schema.model.TypedTxn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// SCHEMA-ON-WRITE: validate and type at write time; reject bad data immediately.
public class SchemaOnWriteStore {
    private static final Logger log = Logger.getLogger(SchemaOnWriteStore.class.getName());
    private final List<TypedTxn> table = new ArrayList<>();

    public void insert(String txnId, String accountId, String amount) {
        // Enforce schema NOW — a bad row never enters the table.
        if (txnId == null || txnId.isBlank() || accountId == null || accountId.isBlank()) {
            log.warning(() -> "WRITE REJECTED: missing key for " + txnId);
            return;
        }
        BigDecimal amt;
        try {
            amt = new BigDecimal(amount);
            if (amt.compareTo(BigDecimal.ZERO) <= 0) throw new NumberFormatException("non-positive");
        } catch (RuntimeException ex) {
            log.warning(() -> "WRITE REJECTED: bad amount '" + amount + "' for " + txnId);
            return;
        }
        table.add(new TypedTxn(txnId, accountId, amt));
        log.info(() -> "WRITE ACCEPTED (schema valid): " + txnId);
    }

    public int size() { return table.size(); }
    public List<TypedTxn> all() { return table; }
}
