package com.bank.schema.conform;

import com.bank.schema.read.SchemaOnReadStore;
import com.bank.schema.write.SchemaOnWriteStore;
import java.util.logging.Logger;

// Reads raw (schema-on-read) and conforms valid rows into the strict store.
public class ConformJob {
    private static final Logger log = Logger.getLogger(ConformJob.class.getName());

    public void conform(SchemaOnReadStore raw, SchemaOnWriteStore strict) {
        log.info("CONFORM: lake (read) → warehouse (write)");
        for (String line : raw.raw()) {
            String[] p = line.split(",");
            strict.insert(p.length > 0 ? p[0] : "",
                          p.length > 1 ? p[1] : "",
                          p.length > 2 ? p[2] : "x");
        }
    }
}
