package com.bank.schema;

import com.bank.schema.conform.ConformJob;
import com.bank.schema.read.SchemaOnReadStore;
import com.bank.schema.write.SchemaOnWriteStore;
import java.util.logging.Logger;

public class SchemaDemo {
    private static final Logger log = Logger.getLogger(SchemaDemo.class.getName());

    public static void main(String[] args) {
        SchemaOnReadStore lake = new SchemaOnReadStore();
        lake.write("T1,SAV2001,1200.00");    // good
        lake.write("T2,CUR3001,5000.00");    // good
        lake.write("T3,SAV2001,oops");       // bad amount — accepted raw anyway

        log.info("=== SCHEMA-ON-READ: structure applied at read time ===");
        log.info("Parsed " + lake.readAs().size() + " of " + lake.raw().size() + " raw records");

        log.info("=== SCHEMA-ON-WRITE: strict warehouse rejects bad data ===");
        SchemaOnWriteStore warehouse = new SchemaOnWriteStore();
        new ConformJob().conform(lake, warehouse);
        log.info("Warehouse accepted " + warehouse.size() + " valid rows");
    }
}
